(() => {
  const box = el => el.getBoundingClientRect();
  const hit = (a, b) => a.left < b.right - 0.5 && b.left < a.right - 0.5 && a.top < b.bottom - 0.5 && b.top < a.bottom - 0.5;
  const bad = [];
  for (const row of document.querySelectorAll('[data-testid="runs-list"] .dsc-run')) {
    const parts = [...row.querySelectorAll('.dsc-run-text > b, .dsc-run-meta, .dsc-run-line, .dsc-cov, .dsc-pick, .dsc-run-remove:not(.ghost), .dsc-run-actions .k-btn')].filter(e => box(e).width > 0);
    const rb = box(row);
    for (let i = 0; i < parts.length; i++) {
      const a = box(parts[i]);
      if (a.right > rb.right + 0.5 || a.left < rb.left - 0.5) bad.push(row.dataset.testid + ': ' + parts[i].className + ' leaves the row');
      for (let j = i + 1; j < parts.length; j++) {
        if (parts[i].contains(parts[j]) || parts[j].contains(parts[i])) continue;
        if (hit(a, box(parts[j]))) bad.push(row.dataset.testid + ': ' + parts[i].className + ' x ' + parts[j].className);
      }
    }
    const name = row.querySelector('.dsc-run-text > b');
    if (name && box(name).width < 60) bad.push(row.dataset.testid + ': name only ' + Math.round(box(name).width) + ' px');
  }
  const list = document.querySelector('[data-testid="runs-list"]');
  list.dataset.geometry = bad.length ? 'bad' : 'ok';
  list.dataset.geometryDetail = bad.slice(0, 6).join(' | ');
})()

(() => {
  const e = document.querySelector('[data-testid="scoreboard-scroll"]');
  if (!e) return;
  const runs = e.querySelectorAll('tbody tr.parent');
  const head = e.querySelector('thead'), first = runs[0];
  let ok;
  if (runs.length <= 10 || !first) ok = e.scrollHeight <= e.clientHeight + 1;
  else {
    const limit = head.offsetHeight + first.offsetHeight * 10 + 2;
    e.scrollTop = Math.min(200, e.scrollHeight - e.clientHeight);
    const th = e.querySelector('thead th');
    const stuck = Math.abs(th.getBoundingClientRect().top - e.getBoundingClientRect().top) <= 1;
    ok = e.clientHeight < e.scrollHeight && e.clientHeight <= limit && stuck;
    e.scrollTop = 0;
  }
  e.dataset.check = ok ? 'ok' : 'bad';
})()
